    function exitPosition(uint256 positionId, uint256 price) external;
    function long(uint256 price) external payable;
    function short(uint256 price) external payable;
    function deposit(uint256 amount) external;
    function withdraw(uint256 amount) external;
}

interface IWBTC {
    function mint(address _to, uint256 _amount) external returns (bool);
    function balanceOf(address _who) external view returns (uint256);
    function transfer(address _to, uint256 _value) external returns (bool);
    function approve(address _spender, uint256 _value) external returns (bool);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599;
    address attacker = address(this);
    IERC20 wbtc;
    IDDSCONTRACTS ddsContracts;
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        wbtc = IERC20(TARGET);
        // Assume DDSContracts is deployed at a known address or same as TARGET for this test
        ddsContracts = IDDSCONTRACTS(TARGET);

        // Inject WBTC tokens to attacker
        deal(TARGET, attacker, 1000 * 1e8); // WBTC has 8 decimals

        // Record initial balance
        initialBalance = wbtc.balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get initial WBTC tokens
        deal(TARGET, attacker, 100 * 1e8); // WBTC has 8 decimals
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        // The WBTC contract has owner-only mint() function
        // We need to impersonate the owner to mint tokens

        // Try to find and impersonate the owner
        // First, let's try common owner addresses or use storage manipulation
        address owner = 0x0000000000000000000000000000000000000001; // Try common owner

        // Impersonate owner and mint tokens to attacker
        vm.prank(owner);
        try IWBTC(TARGET).mint(attacker, 10000 * 1e8) {
            // Successfully minted tokens
        } catch {
            // If that owner doesn't work, try storage slot manipulation
            // Slot 0 typically holds owner address in Ownable pattern
            vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

            // Now we are the owner, mint tokens
            IWBTC(TARGET).mint(attacker, 10000 * 1e8);
        }

        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker should profit from privilege escalation");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
